import pandas as pd
import numpy as np

DATASET_PATH = 'chunks_csv/getisord/getisord_2021_energy.csv'
ADJACENCY_PATH = 'chunks_csv/borough_adjacency.csv'

df_energy = pd.read_csv(DATASET_PATH)
df_adjacency = pd.read_csv(ADJACENCY_PATH)

borough_neighbors = {}
for _, row in df_adjacency.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    if borough not in borough_neighbors:
        borough_neighbors[borough] = []
    borough_neighbors[borough].append(neighbor)

mean_total = df_energy['Energy_value'].mean()
std_dev = df_energy['Energy_value'].std()

results = {}

for index, row in df_energy.iterrows():
    borough = row['borough']
    energy = row['Energy_value']
    if pd.isna(energy):
        continue
    neighbors = borough_neighbors.get(borough, [])
    sum_S = energy
    k = 1
    for neighbor in neighbors:
        neighbor_energy = df_energy.loc[df_energy['borough'] == neighbor, 'Energy_value'].values
        if len(neighbor_energy) > 0 and not pd.isna(neighbor_energy[0]):
            sum_S += neighbor_energy[0]
            k += 1
    expected = k * mean_total
    if std_dev == 0 or k == 0:
        z = 0.0
    else:
        z = (sum_S - expected) / (std_dev * np.sqrt(k))
    results[borough] = z

hot_cold = []
for borough, z in results.items():
    if abs(z) > 1.96:
        if z > 0:
            hot_cold.append(f"{borough} (HOT, z-score = {z:.4f})")
        else:
            hot_cold.append(f"{borough} (COLD, z-score = {z:.4f})")

print("FINAL ANSWER: " + ", ".join(hot_cold) if hot_cold else "FINAL ANSWER: none")
